<?php declare(strict_types=1);namespace StudPulse\Bars;use StudPulse\Http\ApiError;final class BarsQr{public const PATH='/bars_web/QR/Presence/Confirm';public static function link(#[\SensitiveParameter]string$raw):array{if(strlen($raw)>2048||preg_match('/[\x00-\x20\x7f\\\\]/',$raw))throw self::invalid();$url=parse_url($raw);if(!$url||($url['scheme']??'')!=='https'||strcasecmp($url['host']??'','bars.mpei.ru')!==0||isset($url['user'])||isset($url['pass'])||isset($url['port'])||isset($url['fragment'])||strcasecmp($url['path']??'',self::PATH)!==0)throw self::invalid();$pairs=explode('&',$url['query']??'');if(count($pairs)!==2)throw self::invalid();$values=[];foreach($pairs as$pair){if(!preg_match('/^(qrid|s)=([^&]+)$/iD',$pair,$match))throw self::invalid();$key=strtolower($match[1]);if(isset($values[$key]))throw self::invalid();$values[$key]=rawurldecode($match[2]);}if(!preg_match('/^[1-9]\d{0,17}$/D',$values['qrid']??'')||!preg_match('~^[A-Za-z0-9._+/=\x7e-]{1,1500}$~D',$values['s']??''))throw self::invalid();return['id'=>$values['qrid'],'path'=>self::PATH.'?'.$url['query']];}public static function confirmed(string$html,string$id):bool{$page=BarsHtml::document($html);$auth=BarsHtml::authState($html,$page);if(in_array($auth['stage'],['password','two_factor','profiles'],true)){throw new ApiError(401,'BARS_LOGIN_REQUIRED','Подключите сессию БАРС заново и отсканируйте текущий код.');}$row='//body/div[contains(concat(" ",normalize-space(@class)," ")," row ")
            and contains(concat(" ",normalize-space(@class)," ")," mt-2 ")]';foreach($page->query($row)as$node){$identifier=$page->query('./div[1]/span/span[contains(concat(" ",normalize-space(@class)," ")," fw-bold ")]',$node)->item(0);$status=$page->query('./div[2]/span',$node)->item(0);if(!$status)continue;$text=BarsHtml::text($status);if(preg_match('/(?:ссылка.{0,40}не\s*действительна|отсканируйте\s+qr-код\s+повторно)/ui',$text)){throw new ApiError(422,'BARS_QR_EXPIRED','Ссылка БАРС истекла. Отсканируйте текущий QR-код.');}if($identifier&&BarsHtml::text($identifier)===$id&&preg_match('/^Участие (?:успешно|уже) подтверждено[.!]?$/uiD',$text))return true;}return false;}private static function invalid():ApiError{return new ApiError(422,'BARS_QR_INVALID','Отсканируйте QR-код для регистрации БАРС МЭИ.');}}